-- Online tests + admin staff payroll
create table if not exists public.online_tests (id uuid primary key default gen_random_uuid(), title text not null, description text, class text not null, subject text not null, test_type text not null default 'mcq' check (test_type in ('mcq','written','mixed')), duration_minutes integer not null default 60, max_marks integer not null default 100, is_published boolean not null default false, starts_at timestamptz, ends_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.online_test_questions (id uuid primary key default gen_random_uuid(), test_id uuid not null references public.online_tests(id) on delete cascade, question_text text not null, question_type text not null default 'mcq' check (question_type in ('mcq','written')), options jsonb, correct_answer text, marks integer not null default 1, question_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.online_test_submissions (id uuid primary key default gen_random_uuid(), test_id uuid not null references public.online_tests(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, started_at timestamptz not null default now(), submitted_at timestamptz, total_marks_obtained numeric default 0, is_graded boolean not null default false, status text not null default 'in_progress' check (status in ('in_progress','submitted','graded')), created_at timestamptz not null default now(), unique(test_id,student_id));
create table if not exists public.online_test_answers (id uuid primary key default gen_random_uuid(), submission_id uuid not null references public.online_test_submissions(id) on delete cascade, question_id uuid not null references public.online_test_questions(id) on delete cascade, answer_text text, is_correct boolean, marks_awarded numeric default 0, created_at timestamptz not null default now());
alter table public.online_tests enable row level security;
alter table public.online_test_questions enable row level security;
alter table public.online_test_submissions enable row level security;
alter table public.online_test_answers enable row level security;
create policy "Admins can manage online tests" on public.online_tests for all to authenticated using ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin')) with check ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin'));
create policy "Anyone can view published tests" on public.online_tests for select using (is_published=true);
create policy "Admins can manage test questions" on public.online_test_questions for all to authenticated using ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin')) with check ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin'));
create policy "Anyone can read test questions" on public.online_test_questions for select using (true);
create policy "Admins can manage submissions" on public.online_test_submissions for all to authenticated using ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin')) with check ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin'));
create policy "Anyone can insert submissions" on public.online_test_submissions for insert with check (true);
create policy "Anyone can read submissions" on public.online_test_submissions for select using (true);
create policy "Anyone can update submissions" on public.online_test_submissions for update using (true) with check (true);
create policy "Admins can manage answers" on public.online_test_answers for all to authenticated using ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin')) with check ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin'));
create policy "Anyone can insert answers" on public.online_test_answers for insert with check (true);
create policy "Anyone can read answers" on public.online_test_answers for select using (true);
create policy "Anyone can update answers" on public.online_test_answers for update using (true) with check (true);
alter table public.admin_staff add column if not exists monthly_salary numeric not null default 0;
create table if not exists public.admin_salary_records (id uuid primary key default gen_random_uuid(), admin_staff_id uuid not null references public.admin_staff(id) on delete cascade, month text not null, year integer not null, working_days integer not null default 0, days_present numeric not null default 0, half_days integer not null default 0, days_absent integer not null default 0, late_count integer not null default 0, base_salary numeric not null default 0, calculated_salary numeric not null default 0, late_deduction numeric not null default 0, other_deductions numeric not null default 0, bonus numeric not null default 0, final_salary numeric not null default 0, status text not null default 'draft' check (status in ('draft','approved','paid')), notes text, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(admin_staff_id,month,year));
alter table public.admin_salary_records enable row level security;
create policy "Admins manage admin payroll" on public.admin_salary_records for all to authenticated using ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin')) with check ((select role from public.user_profiles where id=auth.uid()) in ('owner','admin'));
